"""Step 7b. Exhibits and numbers added in the revision (run after 07_report.py, 09, 11 and 12): the decomposition of the FCI's effect (paths A, B, C), the matched baseline table, the components
(dollar) comparison, the persistence check, the direct projection, the three FCIs and the sample facts. Writes report/tab_*.tex, report/fig_*.pdf and report/numbers_ext.tex (macros \\bl{...}, same
conventions as numbers.tex), and asserts the claims the text makes about them.   python3 07b_report_extensions.py"""
import numpy as np, pandas as pd
import matplotlib; matplotlib.use("Agg")
import matplotlib.pyplot as plt
import cases as CS
from lib import model as M, daily as D
from lib.paths import RESULTS, REPORT, OUT
from lib import latex_style as LST

BLUE, ORANGE, INK, GREY, GREEN = "#2a78d6", "#eb6834", "#0b0b0b", "#6b6a66", "#2f9e6b"
plt.rcParams.update({"font.size": 8, "axes.edgecolor": GREY, "axes.labelcolor": INK, "text.color": INK, "xtick.color": INK, "ytick.color": INK,
                     "axes.spines.top": False, "axes.spines.right": False, "axes.grid": True, "grid.color": "#e6e5e1", "grid.linewidth": 0.6, "axes.axisbelow": True})
ML = [r"% generated by baseline/07b_report_extensions.py: do not edit"]; BAD = []
def mac(k, v): ML.append(r"\expandafter\gdef\csname bl:" + k + r"\endcsname{" + str(v) + "}")
def chk(name, ok):
    if not ok: BAD.append(name)
def num(x, f="{:.2f}"):
    s = f.format(abs(x)); return ("$-$" if x < 0 and float(s) != 0 else "") + s
def ab(x, f="{:.2f}"): return f.format(abs(x))
BASE = dict(macro="u,pi", start="1996-01", end=None, t2020="in", trend="none")
def load(form, fci, L=12, **kw):
    c = {**BASE, **kw}; return np.load(OUT / "draws" / f"{CS.case_id(dict(form=form, fci=fci, **c))}_L{L}.npz", allow_pickle=True)
pc = lambda a, q: np.percentile(a, q, axis=0)
def star(d, h_idx=None):
    """Significance mark for a draw vector (or array of draws): ** if the 95% interval excludes zero, * if the 90% does."""
    return "$^{**}$" if pc(d, 2.5) * pc(d, 97.5) > 0 else ("$^{*}$" if pc(d, 5) * pc(d, 95) > 0 else "")
def cell(pt, d):
    return num(pt) + star(d), f"[{num(pc(d, 5))}, {num(pc(d, 95))}]"
def sig10(d): return pc(d, 5) * pc(d, 95) > 0
def sig5(d): return pc(d, 2.5) * pc(d, 97.5) > 0
VAR = {"u": 0, "P": 1}
def tbl(cap, label, body, note, spec=None, size="footnotesize", fit=False):
    if fit: body = r"\resizebox{\textwidth}{!}{%" + "\n" + body + "\n}"
    return "\n".join([rf"\begin{{table}}[tp]\centering\{size}\setlength{{\tabcolsep}}{{3pt}}", rf"\caption{{{cap}}}\label{{{label}}}", body,
                      rf"\begin{{flushleft}}\footnotesize\textit{{Notes:}} {note}\end{{flushleft}}", r"\end{table}"])
def two(cells): return " & ".join(c[0] for c in cells) + r"\\", " & ".join(rf"{{\scriptsize {c[1]}}}" for c in cells) + r"\\"

# =============================================================== 1. decomposition: paths A, B, C
FORMS = ("nom", "real", "rstar"); NAMES = {"nom": "Nominal", "real": "Real", "rstar": "Neutral rate ($r^*$-gap)"}
DEC = {}
for f in FORMS:
    A, C = load(f, f), load(f, 0)
    pts = dict(A=A["s0"], B=A["s0B"], C=C["s0"]); drs = dict(A=A["sd"], B=A["sdB"], C=C["sd"])
    DEC[f] = dict(pts=pts, drs=drs, bF=float(D.window_impact(D.event_index())[1]), ord0=float(A["ord0"]), ordd=A["ordd"], f0=A["f0"], fd=A["fd"])
def con(f, a, b, v, h):
    x = DEC[f]; j = VAR[v]; return x["pts"][a][h, j] - x["pts"][b][h, j], x["drs"][a][:, h, j] - x["drs"][b][:, h, j]

# identity check: A-B and B-C sum to A-C at every horizon and in every draw
for f in FORMS:
    for v in ("u", "P"):
        for h in range(37):
            p1, d1 = con(f, "A", "B", v, h); p2, d2 = con(f, "B", "C", v, h); p3, d3 = con(f, "A", "C", v, h)
            chk("A-B plus B-C equals A-C", abs(p1 + p2 - p3) < 1e-9 and np.abs(d1 + d2 - d3).max() < 1e-9)
# pairing check: the draws of A and C are positively related (common announcements, months, daily rows)
for f in FORMS:
    cc = np.corrcoef(DEC[f]["drs"]["A"][:, 24, 1], DEC[f]["drs"]["C"][:, 24, 1])[0, 1]; mac(f"dc:{f}:corrAC", f"{cc:.2f}")
    chk(f"{f}: paired draws of A and C are positively correlated at 24 m (price level)", cc > 0.2)

def dec_rows(f, label, paths=True):
    rows = []
    x = DEC[f]
    if paths:
        for k, nm, ini in (("A", "A. Yield and FCI, window FCI movement", f"{x['bF']:.2f}"), ("B", "B. Same model, ordinary FCI movement", f"{x['ord0']:.2f}"), ("C", "C. Yield alone", "--")):
            cells = [(num(x["pts"][k][24, VAR[v]]) + star(x["drs"][k][:, 24, VAR[v]]), f"[{num(pc(x['drs'][k][:, 24, VAR[v]], 5))}, {num(pc(x['drs'][k][:, 24, VAR[v]], 95))}]") for v in ("u", "P")]
            a, b = two(cells); rows += [f"{nm} & {ini} & " + a, " & & " + b]
    for a_, b_, nm in (("A", "C", "A $-$ C: effect of adding the FCI"), ("A", "B", "A $-$ B: initial FCI movement, dynamics fixed"), ("B", "C", "B $-$ C: the financial state and propagation")):
        cells = []
        for v in ("u", "P"):
            p, d = con(f, a_, b_, v, 24); cells.append(cell(p, d))
        ini = {"AC": "", "AB": f"{x['bF'] - x['ord0']:.2f}", "BC": ""}[a_ + b_]
        a, b = two(cells); rows += [f"{nm} & {ini} & " + a, " & & " + b]
    return rows
def dec_table():
    body = [r"\begin{tabular}{lrcc}\toprule", r" & Initial FCI & Unemployment gap (pp) & Price level (\%)\\ & movement & 24 months & 24 months\\ \midrule"]
    body += [r"\multicolumn{4}{l}{\textit{Neutral-rate version (baseline)}}\\"] + dec_rows("rstar", "")
    for f in ("nom", "real"):
        body += [r"\addlinespace" + rf"\multicolumn{{4}}{{l}}{{\textit{{{NAMES[f]} version}}}}\\"] + dec_rows(f, "", paths=False)
    body += [r"\bottomrule\end{tabular}"]
    note = (r"Per +1 pp on the two-year yield in the window. Path A is the baseline model with the yield and the FCI, started with the window movement of the FCI (first column). Path B is the same fitted model started with the FCI movement that "
            r"ordinarily accompanies a 1 pp innovation in the yield (Appendix~\ref{app:details}). Path C is the model with the yield alone. All three use the same sample, announcements, calendar and bootstrap draws, so the contrasts are paired and "
            r"A $-$ B and B $-$ C add to A $-$ C in every draw. Brackets: 90\% intervals; $^{**}$, $^{*}$: 5 and 10 percent levels.")
    (REPORT / "tab_decomp.tex").write_text(tbl("The Effect of the FCI: Initial Movement and Propagation", "tab:decomp", "\n".join(body), note) + "\n")
dec_table()

BANDS = lambda ax, h, d, col, a: (ax.fill_between(h, pc(d, 5), pc(d, 95), color=col, alpha=a, lw=0), ax.fill_between(h, pc(d, 16), pc(d, 84), color=col, alpha=min(2 * a, 0.4), lw=0))
def fig_decomp():
    x = DEC["rstar"]; h = np.arange(37); fig, axs = plt.subplots(2, 2, figsize=(7.2, 5.4), sharex=True)
    for j, (v, ylab) in enumerate((("u", "Unemployment gap (pp)"), ("P", "Core PCE price level (%)"))):
        ax = axs[0, j]; ax.axhline(0, color=GREY, lw=0.8); k = VAR[v]
        BANDS(ax, h, x["drs"]["A"][:, :, k], BLUE, 0.12); ax.plot(h, x["pts"]["A"][:, k], color=BLUE, lw=2.0, label="A: yield and FCI, window FCI movement")
        ax.plot(h, x["pts"]["B"][:, k], color=GREEN, lw=1.8, ls="-.", label="B: same model, ordinary FCI movement"); ax.plot(h, x["pts"]["C"][:, k], color=ORANGE, lw=1.8, ls="--", label="C: yield alone")
        ax.set_ylabel(ylab); ax.set_title("Paths" if j == 0 else "", fontsize=8.5)
        ax = axs[1, j]; ax.axhline(0, color=GREY, lw=0.8)
        for (a_, b_), col, ls, lab in ((("A", "B"), BLUE, "-", "A $-$ B: initial FCI movement"), (("B", "C"), GREEN, "-.", "B $-$ C: financial state and propagation")):
            pt = x["pts"][a_][:, k] - x["pts"][b_][:, k]; d = x["drs"][a_][:, :, k] - x["drs"][b_][:, :, k]; ax.fill_between(h, pc(d, 5), pc(d, 95), color=col, alpha=0.14, lw=0); ax.plot(h, pt, color=col, ls=ls, lw=1.8, label=lab)
        ax.plot(h, x["pts"]["A"][:, k] - x["pts"]["C"][:, k], color=INK, lw=1.0, ls=":", label="A $-$ C: total"); ax.set_xlabel("Months after the policy move"); ax.set_ylabel(ylab)
        ax.set_title("Contrasts (90% bands)" if j == 0 else "", fontsize=8.5); ax.set_xlim(0, 36)
    h1, l1 = axs[0, 0].get_legend_handles_labels(); h2, l2 = axs[1, 0].get_legend_handles_labels()
    fig.legend(h1 + h2, l1 + l2, loc="lower center", ncol=2, frameon=False, fontsize=7.2)
    fig.tight_layout(rect=[0, 0.1, 1, 1]); fig.savefig(REPORT / "fig_decomp.pdf"); plt.close(fig)
fig_decomp()
for f in FORMS:
    for v in ("u", "P"):
        for h in (12, 24, 36):
            for a_, b_, nm in (("A", "C", "AC"), ("A", "B", "AB"), ("B", "C", "BC")):
                p, d = con(f, a_, b_, v, h); k = f"dc:{f}:{nm}:{v}:{h}"; mac(k, num(p)); mac(k + ":abs", ab(p)); mac(k + ":lo", num(pc(d, 5))); mac(k + ":hi", num(pc(d, 95))); mac(k + ":sig", "significant" if sig10(d) else "not significant")
            for nm in "ABC":
                mac(f"dc:{f}:{nm}:{v}:{h}", num(DEC[f]["pts"][nm][h, VAR[v]]))
    x = DEC[f]; mac(f"dc:{f}:bF", f"{x['bF']:.2f}"); mac(f"dc:{f}:ord", f"{x['ord0']:.2f}"); mac(f"dc:{f}:ord:lo", f"{pc(x['ordd'], 5):.2f}"); mac(f"dc:{f}:ord:hi", f"{pc(x['ordd'], 95):.2f}")
    mac(f"dc:{f}:diff", f"{x['bF'] - x['ord0']:.2f}"); mac(f"dc:{f}:ratio:u", f"{con(f, 'A', 'B', 'u', 24)[0] / con(f, 'A', 'C', 'u', 24)[0]:.2f}")
# timing: horizon of the largest A-C and A-B unemployment effect, and of the B-C effect
x = DEC["rstar"]; mac("dc:peak:AC:u", int(np.argmax(x["pts"]["A"][:, 0] - x["pts"]["C"][:, 0]))); mac("dc:peak:AB:u", int(np.argmax(x["pts"]["A"][:, 0] - x["pts"]["B"][:, 0]))); mac("dc:peak:BC:u", int(np.argmax(x["pts"]["B"][:, 0] - x["pts"]["C"][:, 0])))
# sensitivity of B to the ordinary loading (point estimates): the response is linear in the initial FCI movement phi, so A - B(phi) for any phi needs two simulations
def point_model(form="rstar", fci="rstar", L=12):
    mv = ["u", "pi"]; idx0, pos0, _, _ = M.events(1); Xd, Yd = M.har_rows(form, fci, mv, None, "in"); Bd0 = M.har_fit(Xd, Yd, fci); X, Y = M.macro_data(form, fci, mv, L, "1996-01", None, "in", "none"); C0 = np.linalg.lstsq(X, Y, rcond=None)[0]
    return lambda phi: M.to_level(M.irf_b(Bd0, C0, 2, 2, L, np.r_[1.0, phi], pos0)[0])
pm = point_model(); dpt = pm(DEC["rstar"]["bF"]) - pm(DEC["rstar"]["ord0"]); mac("dc:chk:AB", f"{dpt[24, 0]:.3f}")
chk("path B recomputed from the point model equals the stored path", abs(pm(DEC["rstar"]["ord0"])[24, 1] - DEC["rstar"]["pts"]["B"][24, 1]) < 1e-9)
from lib import monthly as MO
MAC_ = M.MAC[["u", "pi"]]; Dm = MAC_.join(M.fin_eom("rstar", "rstar"), how="inner").dropna(); Xm, Ym, _ = MO.design(Dm, 12, "1996-01"); rm = Ym - Xm @ np.linalg.lstsq(Xm, Ym, rcond=None)[0]
ord_m = float(np.cov(rm[:, 3], rm[:, 2])[0, 1] / np.var(rm[:, 2], ddof=1)); mac("dc:ordm", f"{ord_m:.2f}")
sens = {phi: pm(phi) for phi in (0.0, DEC["rstar"]["ord0"], ord_m, DEC["rstar"]["bF"])}
mac("dc:sens:u:phi0", num(sens[DEC["rstar"]["bF"]][24, 0] - sens[0.0][24, 0])); mac("dc:sens:u:phim", num(sens[DEC["rstar"]["bF"]][24, 0] - sens[ord_m][24, 0]))
mac("dc:sens:P:phi0", num(sens[DEC["rstar"]["bF"]][24, 1] - sens[0.0][24, 1])); mac("dc:sens:P:phim", num(sens[DEC["rstar"]["bF"]][24, 1] - sens[ord_m][24, 1]))
mac("dc:sens:u:BCm", num(sens[ord_m][24, 0] - DEC["rstar"]["pts"]["C"][24, 0])); mac("dc:sens:P:BCm", num(sens[ord_m][24, 1] - DEC["rstar"]["pts"]["C"][24, 1]))

# =============================================================== 2. matched baseline table (24 months, without and with the FCI, paired differences)
def matched():
    body = [r"\begin{tabular}{lcccccc}\toprule", r" & \multicolumn{3}{c}{Unemployment gap (pp)} & \multicolumn{3}{c}{Price level (\%)}\\ \cmidrule(lr){2-4}\cmidrule(lr){5-7}",
            r"Yield measure & Yield alone & Yield and FCI & Difference & Yield alone & Yield and FCI & Difference\\ \midrule"]
    for f in FORMS:
        cells = []
        for v in ("u", "P"):
            k = VAR[v]; cells += [cell(DEC[f]["pts"]["C"][24, k], DEC[f]["drs"]["C"][:, 24, k]), cell(DEC[f]["pts"]["A"][24, k], DEC[f]["drs"]["A"][:, 24, k]), cell(*con(f, "A", "C", v, 24))]
        a, b = two(cells); body += [f"{NAMES[f]} & " + a, " & " + b]
        if f != "rstar": body.append(r"\addlinespace")
    body += [r"\bottomrule\end{tabular}"]
    note = (r"Responses 24 months after a policy move that raises the two-year yield 1 pp in the window, 1996--2026, 12 lags. Differences are computed on common bootstrap draws before rounding. Brackets: 90\% intervals; $^{**}$, $^{*}$: 5 and 10 percent levels. "
            r"Responses at 12 and 36 months and at 3 and 6 lags are in Appendix Tables~\ref{tab:mainB} and~\ref{tab:lags}.")
    (REPORT / "tab_matched.tex").write_text(tbl("Responses without and with the FCI After Two Years", "tab:matched", "\n".join(body), note) + "\n")
matched()

# =============================================================== 3. components: the dollar and the weights restriction
SPECS = (("A", "rstar", "Index (baseline)"), ("R", "cmpR", "Index, components' daily block"), ("E", "cmpE", "Equities free"), ("F", "cmp", "All three free"))
CMP = {}
for start in ("1996-01", "1973-01"):
    for sp, fci, lab in SPECS:
        if sp == "A" and start == "1973-01":
            z = load("rstar", "rstar", start=start)
        else: z = load("rstar", fci if sp != "A" else "rstar", start=start)
        CMP[(start, sp)] = z
def cmp_cell(start, sp, v):
    z = CMP[(start, sp)]; k = VAR[v]; return cell(z["s0"][24, k], z["sd"][:, 24, k])
def cmp_diff(start, a, b, v):
    k = VAR[v]; return cell(CMP[(start, a)]["s0"][24, k] - CMP[(start, b)]["s0"][24, k], CMP[(start, a)]["sd"][:, 24, k] - CMP[(start, b)]["sd"][:, 24, k])
WTT = pd.read_csv(RESULTS / "weights_test.csv")
def comp_table():
    body = [r"\begin{tabular}{llcccccc}\toprule", r" & & \multicolumn{4}{c}{Monthly equations with} & \multicolumn{2}{c}{Difference from the index}\\ \cmidrule(lr){3-6}\cmidrule(lr){7-8}",
            r"Start & Response & Index (baseline) & Index, three-component daily block & Equities free & All three free & Equities free & All three free\\ \midrule"]
    for si, start in enumerate(("1996-01", "1973-01")):
        if si: body.append(r"\addlinespace")
        for v, lab in (("P", "Price level, 24 m (\\%)"), ("u", "Unemployment gap, 24 m (pp)")):
            cells = [cmp_cell(start, sp, v) for sp in ("A", "R", "E", "F")] + [cmp_diff(start, "E", "R", v), cmp_diff(start, "F", "R", v)]
            a, b = two(cells); body += [f"{start[:4]} & {lab} & " + a, " & & " + b]
    body += [r"\bottomrule\end{tabular}"]
    note = (r"$r^*$-gap yield and FCI, 12 lags, per +1 pp on the two-year yield in the window. The last three columns share one daily block (the three components and the two-year yield), so they differ only in the monthly equations: the FCI built from the components as one variable, "
            r"equities separate with the 10-year yield and the dollar as one variable, or all three separate. The difference columns are computed on common bootstrap draws. The first column is the baseline model with its own daily block. "
            r"Brackets: 90\% intervals; $^{**}$, $^{*}$: 5 and 10 percent levels. Nominal and real versions: Appendix Table~\ref{tab:appR4c}.")
    (REPORT / "tab_components.tex").write_text(tbl("Price and Unemployment Responses with the Components Entered Separately", "tab:components", "\n".join(body), note, size="scriptsize", fit=True) + "\n")
comp_table()
for start in ("1996-01", "1973-01"):
    t = start[:4]
    for sp in "AREF":
        for v in ("u", "P"):
            z = CMP[(start, sp)]; k = VAR[v]; key = f"cp:{t}:{sp}:{v}"; mac(key, num(z["s0"][24, k])); mac(key + ":abs", ab(z["s0"][24, k])); mac(key + ":lo", num(pc(z["sd"][:, 24, k], 5))); mac(key + ":hi", num(pc(z["sd"][:, 24, k], 95)))
            mac(key + ":sig", "significant" if sig10(z["sd"][:, 24, k]) else "not significant"); mac(key + ":sig5", "significant" if sig5(z["sd"][:, 24, k]) else "not significant")
    for a_, b_ in (("E", "R"), ("F", "R"), ("F", "E")):
        for v in ("u", "P"):
            k = VAR[v]; pt = CMP[(start, a_)]["s0"][24, k] - CMP[(start, b_)]["s0"][24, k]; d = CMP[(start, a_)]["sd"][:, 24, k] - CMP[(start, b_)]["sd"][:, 24, k]
            key = f"cp:{t}:{a_}{b_}:{v}"; mac(key, num(pt)); mac(key + ":lo", num(pc(d, 5))); mac(key + ":hi", num(pc(d, 95))); mac(key + ":sig", "significant" if sig10(d) else "not significant")
# tests (Table 8 extended)
def wt_table():
    TN = {"all": "Three components equal", "yd": "10-year yield equal to dollar, equities free", "eq": "Equities equal to yield and dollar, which are equal"}
    body = [r"\begin{tabular}{lcccccc}\toprule", r" & \multicolumn{2}{c}{Three components equal} & \multicolumn{2}{c}{Yield and dollar equal, equities free} & \multicolumn{2}{c}{Equities equal to yield and dollar}\\ \cmidrule(lr){2-3}\cmidrule(lr){4-5}\cmidrule(lr){6-7}",
            r"Version & Unemployment & Inflation & Unemployment & Inflation & Unemployment & Inflation\\ \midrule"]
    for start, lab in (("1996-01", ""), ("1973-01", ", start 1973")):
        for step in FORMS:
            cells = []
            for test in ("all", "yd", "eq"):
                for eq in ("u", "pi"):
                    r = WTT[(WTT.test == test) & (WTT.step == step) & (WTT.lags == 12) & (WTT["eq"] == eq) & (WTT.start == start)].iloc[0]; cells.append(f"{r.p_boot:.3f}")
            body.append(f"{CS.FORMS[step]}{lab} & " + " & ".join(cells) + r"\\")
        if start == "1996-01": body.append(r"\addlinespace")
    body += [r"\bottomrule\end{tabular}"]
    note = (r"Bootstrap $p$-values of Wald statistics (heteroskedasticity-robust) for the restriction that the coefficients on the weighted components are equal at each lag of the monthly equation, 12 lags: the three components (24 restrictions); the 10-year yield and the dollar with equities free (12); "
            r"equities and the yield-dollar variable, the yield and dollar being equal (12). Residuals are resampled in moving blocks of 12 months under the restricted equation, 999 draws. Wald statistics and 3 and 6 lags are in Appendix Table~\ref{tab:wtfull}.")
    (REPORT / "tab_weights_test.tex").write_text(tbl("Tests of the Proportional-Weights Restriction", "tab:weightstest", "\n".join(body), note, fit=True) + "\n")
    rows = []
    for start in ("1996-01", "1973-01"):
        for step in FORMS:
            for L in (12, 6, 3):
                cells = []
                for test in ("all", "yd", "eq"):
                    for eq in ("u", "pi"):
                        r = WTT[(WTT.test == test) & (WTT.step == step) & (WTT.lags == L) & (WTT["eq"] == eq) & (WTT.start == start)].iloc[0]; cells.append(f"{r.wald:.1f} ({r.p_boot:.3f})")
                rows.append(f"{CS.FORMS[step]}, {start[:4]} & {L} & " + " & ".join(cells) + r"\\")
    body2 = [r"\begin{tabular}{llcccccc}\toprule", r" & & \multicolumn{2}{c}{Three equal} & \multicolumn{2}{c}{Yield = dollar} & \multicolumn{2}{c}{Equities = rest}\\ \cmidrule(lr){3-4}\cmidrule(lr){5-6}\cmidrule(lr){7-8}", r"Version, start & Lags & U & Inflation & U & Inflation & U & Inflation\\ \midrule", *rows, r"\bottomrule\end{tabular}"]
    (REPORT / "tab_wt_full.tex").write_text(tbl("Weights Tests: Wald Statistics and Bootstrap p-Values by Lag Length", "tab:wtfull", "\n".join(body2), r"Wald statistic with the bootstrap $p$-value in parentheses; U = unemployment gap equation. Tests as in Table~\ref{tab:weightstest}.", size="scriptsize", fit=True) + "\n")
wt_table()
def wp(test, step, eq, start="1996-01", L=12): return WTT[(WTT.test == test) & (WTT.step == step) & (WTT.lags == L) & (WTT["eq"] == eq) & (WTT.start == start)].iloc[0].p_boot
for t_, st in (("96", "1996-01"), ("73", "1973-01")):
    for test in ("all", "yd", "eq"):
        for step in FORMS:
            for eq in ("u", "pi"): mac(f"wt2:{t_}:{test}:{step}:{eq}", f"{wp(test, step, eq, st):.3f}")

# =============================================================== 4. persistence beyond the window (event-based responses on the same clock as the model)
PER = pd.read_csv(RESULTS / "persistence.csv") if (RESULTS / "persistence.csv").exists() else None
def persistence():
    z = load("rstar", "rstar"); f0, fd = z["fday0"], z["fdayd"]; days = np.arange(67)
    P = PER[(PER.base == "window plus later closes") & (~PER.controls)].set_index(["series", "measure"]); PC = PER[(PER.base == "window plus later closes") & (PER.controls)].set_index(["series", "measure"])
    fig, axs = plt.subplots(1, 2, figsize=(7.2, 3.1))
