# sums of the lag coefficients on the three weighted components in the unrestricted monthly equations (r*-gap, 12 lags): what the conditional coefficients say
def coef_sums():
    for start, t in (("1996-01", "96"), ("1973-01", "73")):
        L = 12; X, Y = M.macro_data("rstar", "cmp", ["u", "pi"], L, start, None, "in", "none"); n, k = X.shape; K = 2; nd = 4; XX = np.linalg.inv(X.T @ X)
        for j, nm in enumerate(("u", "pi")):
            b = XX @ X.T @ Y[:, j]; r = Y[:, j] - X @ b; V = XX @ (X.T * (r ** 2)) @ X @ XX * n / (n - k)
            for c, lab in ((1, "y10"), (2, "eq"), (3, "usd")):
                w = np.zeros(k); w[[1 + K * L + l * nd + c for l in range(L)]] = 1; mac(f"cp:coef:{t}:{nm}:{lab}", num(w @ b)); mac(f"cp:coef:{t}:{nm}:{lab}:se", f"{np.sqrt(w @ V @ w):.2f}")
coef_sums()


# sensitivity to the first-month average of the financial variables: the macro response to a change in the event month's average of (yield, FCI), through the monthly equations of the baseline (partial: no feedback into the daily block)
def persistence_sensitivity():
    if PER is None: return
    X, Y = M.macro_data("rstar", "rstar", ["u", "pi"], 12, "1996-01", None, "in", "none"); C = np.linalg.lstsq(X, Y, rcond=None)[0]; K, L, nd = 2, 12, 2
    A = C[1:1 + K * L].T.reshape(K, L, K); G = C[1 + K * L:1 + K * L + nd * L].T.reshape(K, L, nd)
    def resp(dl, n=1):
        m = np.zeros((37, K))
        for t in range(1, 37): m[t] = sum(A[:, l - 1] @ m[t - l] for l in range(1, L + 1) if t - l >= 1) + sum(G[:, t - j - 1] @ dl for j in range(n) if 1 <= t - j <= L)
        return M.to_level(m)
    P = PER[(PER.measure == "avg22") & (PER.controls == False)].set_index(["series", "base"])
    for lab, base in (("w", "window plus later closes"), ("p", "pre-event close")):
        dl = np.array([P.loc[("y", base)].est - P.loc[("y", base)].model, P.loc[("f", base)].est - P.loc[("f", base)].model]); r = resp(dl)
        mac(f"pe:sens:{lab}:dy", num(dl[0])); mac(f"pe:sens:{lab}:df", num(dl[1])); mac(f"pe:sens:{lab}:u24", num(r[24, 0])); mac(f"pe:sens:{lab}:P24", num(r[24, 1])); mac(f"pe:sens:{lab}:u12", num(r[12, 0]))
        r3 = resp(dl, 3); mac(f"pe:sens:{lab}:u24x3", num(r3[24, 0])); mac(f"pe:sens:{lab}:P24x3", num(r3[24, 1])); r2 = resp(np.array([0.0, dl[1]]), 3); mac(f"pe:sens:{lab}:fu24x3", num(r2[24, 0])); mac(f"pe:sens:{lab}:fP24x3", num(r2[24, 1]))
    unit = resp(np.array([0.0, 1.0]), 3); mac("pe:sens:unit:u24", num(unit[24, 0])); mac("pe:sens:unit:P24", num(unit[24, 1]))
persistence_sensitivity()


def persistence_rho():
    """Partial sensitivity: scale the model's FCI path from month 2 on (days 44 and later) by the ratio of the direct to the model estimate at day 66, and trace the macro response through the baseline monthly equations (no feedback into the daily block)."""
    if PER is None: return
    X, Y = M.macro_data("rstar", "rstar", ["u", "pi"], 12, "1996-01", None, "in", "none"); C = np.linalg.lstsq(X, Y, rcond=None)[0]; K, L, nd = 2, 12, 2
    A = C[1:1 + K * L].T.reshape(K, L, K); G = C[1 + K * L:1 + K * L + nd * L].T.reshape(K, L, nd); z = load("rstar", "rstar"); f0 = z["f0"].copy()
    def resp(fb):
        m = np.zeros((37, K))
        for t in range(1, 37): m[t] = sum(A[:, l - 1] @ m[t - l] for l in range(1, L + 1) if t - l >= 1) + sum(G[:, l - 1] @ fb[t - l] for l in range(1, L + 1) if t - l >= 0)
        return M.to_level(m)
    base = resp(f0); chk("monthly response from the model's financial path reproduces the baseline", abs(base[24, 0] - z["s0"][24, 0]) < 0.02 and abs(base[24, 1] - z["s0"][24, 1]) < 0.02)
    r = PER[(PER.series == "f") & (PER.measure == "h66") & (PER.base == "window plus later closes") & (~PER.controls)].iloc[0]
    for lab, e in (("pt", r.est), ("lo", r.lo), ("hi", r.hi)):
        rho = e / r.model; fb = f0.copy(); fb[2:, 1] *= rho; q = resp(fb); mac(f"pe:rho:{lab}", f"{rho:.2f}"); mac(f"pe:rho:{lab}:u24", num(q[24, 0])); mac(f"pe:rho:{lab}:P24", num(q[24, 1])); mac(f"pe:rho:{lab}:du", num(q[24, 0] - base[24, 0])); mac(f"pe:rho:{lab}:dP", num(q[24, 1] - base[24, 1]))
    mac("pe:rho:base:u24", num(base[24, 0])); mac("pe:rho:base:P24", num(base[24, 1]))
persistence_rho()


if PER is not None:                                    # initial level at the announcement day's close instead of the window (the window-to-close gap of the FCI)
    gap_f = float(PER[(PER.series == "f") & (PER.measure == "gap")].est.iloc[0]); bF_ = DEC["rstar"]["bF"]; w_, c_ = pm(bF_), pm(bF_ + gap_f)
