        chk("FCI: model inside the direct interval at 5, 22 and 66 days", all(P1.loc[("f", m)].lo <= P1.loc[("f", m)].model <= P1.loc[("f", m)].hi for m in ("h5", "h22", "h66")))
        chk("FCI: 66-day interval contains a complete reversal (lower bound below zero) and the model", P1.loc[("f", "h66")].lo < 0 < P1.loc[("f", "h66")].model)
        chk("FCI: first-month average above the model's, model below the direct interval (model clock)", P1.loc[("f", "avg22")].model < P1.loc[("f", "avg22")].lo)
